"""Generate explicit version-one state accessors from reviewed member/event lists, never runtime reflection."""
import argparse
import collections
import json
from pathlib import Path
import re

REPO = Path(__file__).resolve().parents[1]


def load(path):
    """Read a bounded build-time schema or Roslyn inventory."""
    return json.loads(Path(path).read_text(encoding='utf-8-sig'))


def write(path, text, check):
    """Verify generated bytes or write and immediately reread them after generation."""
    path = Path(path)
    data = text.encode('utf-8')
    if check:
        if not path.exists() or path.read_bytes() != data:
            raise AssertionError('Generated state source is stale: ' + str(path))
    else:
        path.write_bytes(data)
        if path.read_bytes() != data:
            raise OSError('State source write verification failed.')


def decorate(events, check):
    """Add lazy descriptors without changing executed callback bodies or serializing values on hot sample paths."""
    by_file = collections.defaultdict(list)
    for row in events:
        by_file[row['file']].append(row)
    callbacks = {}
    for name, rows in by_file.items():
        path = REPO / name
        text = path.read_bytes().decode('utf-8-sig')
        # The initial source offsets are intentionally used only once; later checks use the already decorated text.
        initial = all(text[v['start']:v['end']].startswith(v['receiver'] + '.ScheduleAfter(') and
                      v['operation'] not in text[v['start']:v['end']] for v in rows)
        additions = {}
        for row in rows:
            args = row['arguments']
            suffix = ', this, "' + row['operation'] + '"'
            if args:
                suffix += ', () => StateValues.Pack(' + ', '.join(v[2] for v in args) + ')'
            additions[row['operation']] = suffix
        if initial:
            old_text = text
            for row in sorted(rows, key=lambda v: v['end'], reverse=True):
                at = row['end'] - 1
                assert text[at] == ')', (name, at)
                text = text[:at] + additions[row['operation']] + text[at:]
            if check:
                raise AssertionError('Scheduled descriptors not installed: ' + name)
            write(path, text, False)
        else:
            old_text = None
            for row in rows:
                if ', this, "' + row['operation'] + '"' not in text:
                    raise AssertionError('Missing named operation: ' + name + '/' + row['operation'])
        for row in rows:
            callback = row['callback']
            # A restored outer callback must retain descriptors on nested future callbacks too.
            for child in rows:
                if child['start'] > row['start'] and child['end'] < row['end']:
                    original = child['receiver'] + '.ScheduleAfter(' + child['delay'] + ', ' + child['callback'] + ')'
                    updated = original[:-1] + additions[child['operation']] + ')'
                    if original not in callback:
                        raise AssertionError('Nested callback changed without a schema review.')
                    callback = callback.replace(original, updated)
            callbacks[(row['owner'], row['operation'])] = callback
    return callbacks


def accessor(node, events, callbacks):
    """Emit ordinary statically checked C# field access for one component or owned nested object."""
    ns, typ = node['namespace'], node['type']
    key = ns + '.' + typ
    save, restore, children = [], [], []
    for field in node['fields']:
        name, value_type, mode = field['name'], field['type'], field['mode']
        literal = json.dumps(name)
        if mode == 'excluded':
            continue
        if mode == 'children':
            if value_type.endswith('[]') or value_type.startswith('List<'):
                children.append(f'for (int i = 0; i < {name}.{"Length" if value_type.endswith("[]") else "Count"}; i++) yield return ("{name}/" + i, {name}[i]);')
            else:
                children.append(f'if ({name} is {{ }} child_{name.lstrip("_")}) yield return ("{name}", child_{name.lstrip("_")});')
            continue
        source = name + '.ToArray()' if mode in ['queue', 'set'] else name + '.ToString()' if mode == 'builder' else name
        save.append(f'w.Value({literal}, {source});')
        if mode == 'value':
            restore.append(f'{name} = r.Value<{value_type}>({literal});')
        elif mode == 'invariant':
            restore.append(f'r.Invariant({literal}, {name});')
        elif mode == 'array':
            restore.append(f'r.Array({literal}, {name});')
        elif mode == 'planes':
            restore.append(f'r.Planes({literal}, {name});')
        elif mode in ['queue', 'set']:
            element = value_type[value_type.index('<') + 1:-1]
            method = 'Enqueue' if mode == 'queue' else 'Add'
            restore.append(f'{name}.Clear(); foreach (var item in r.Sequence<{element}>({literal})) {name}.{method}(item);')
        elif mode == 'builder':
            restore.append(f'{name}.Clear(); {name}.Append(r.Value<string>({literal}));')
        else:
            raise ValueError(mode)
    restore.extend(node.get('afterLoad', []))
    statements = [
        '    /// <summary>Captures every version-one data member explicitly enumerated in the reviewed schema.</summary>',
        '    public StateBlock SaveState()', '    {', f'        var w = new StateWriter("{key}");',
        *('        ' + v for v in save), '        return w.Finish();', '    }', '',
        '    /// <summary>Restores checked members into a newly prepared object; factory dependencies retain their ownership.</summary>',
        '    public void LoadState(StateBlock state)', '    {', f'        var r = new StateReader(state, "{key}");',
        *('        ' + v for v in restore), '        r.Finish();', '    }', '',
        '    /// <summary>Enumerates only owned nested state objects; shared graph references are excluded.</summary>',
        '    public IEnumerable<(string Name, IStateObject Value)> StateChildren', '    {', '        get', '        {',
        *('            ' + v for v in children), '            yield break;', '        }', '    }']
    own = [v for v in events if v['owner'] == key]
    if own:
        statements.extend(['', '    /// <summary>Binds a known scheduled operation to its checked typed captured arguments.</summary>',
                           '    public Action BindStateEvent(string operation, System.Text.Json.JsonElement[] payload)', '    {',
                           '        switch (operation)', '        {'])
        for row in own:
            args = row['arguments']
            statements.extend([f'            case "{row["operation"]}":', '            {',
                               f'                if (payload.Length != {len(args)}) throw new InvalidDataException("Scheduled operation shape differs.");'])
            for i, (name, value_type, _) in enumerate(args):
                statements.append(f'                {value_type} {name} = StateValues.Read<{value_type}>(payload[{i}]);')
            if any(v[0] == 'timerIndex' for v in args):
                statements.extend(['                if ((uint)timerIndex >= _timers.Length) throw new InvalidDataException("Invalid FM timer index.");',
                                   '                var timer = _timers[timerIndex];'])
            callback = callbacks[(key, row['operation'])]
            statements.append('                return ' + callback.replace('\n', '\n                ') + ';')
            statements.append('            }')
        statements.extend(['            default: throw new InvalidDataException("Unknown scheduled operation.");', '        }', '    }'])
    return '\n'.join(statements)


def main(args):
    """Validate exhaustive field coverage, generate all partials and install lazy event descriptors."""
    schema = load(REPO / 'docs/state-schema-v1.json')
    events = load(REPO / 'docs/state-events-v1.json')['events']
    inventory = load(args.inventory)
    for key, node in schema['nodes'].items():
        actual = {(v['name'], v['valueType']) for v in inventory if v['category'] in ['field', 'property'] and
                  v['ns'] + '.' + v['type'] == key and not any(m in v['modifiers'].split() for m in ['static', 'const'])}
        expected = {(v['name'], v['type']) for v in node['fields']}
        if actual != expected:
            raise AssertionError('Unreviewed component fields: ' + key + ': ' + str(actual ^ expected))
        primary = {(v['name'], v['valueType']) for v in inventory if v['category'] == 'primary' and v['ns'] + '.' + v['type'] == key}
        if primary != {(v['name'], v['type']) for v in node.get('primaryParameters', [])}:
            raise AssertionError('Unreviewed primary-constructor dependencies: ' + key)
    callbacks = decorate(events, args.check)
    actual_events = collections.Counter((v['ns'] + '.' + v['type'], v['receiver'], v['delay'].strip(), v['callback'].replace('\r\n', '\n').strip())
                                        for v in inventory if v['category'] == 'schedule')
    expected_events = collections.Counter((v['owner'], v['receiver'], v['delay'].strip(), callbacks[(v['owner'], v['operation'])].replace('\r\n', '\n').strip()) for v in events)
    if actual_events != expected_events:
        raise AssertionError('Scheduled callback body/arguments changed without updating the reviewed operation schema.')
    grouped = collections.defaultdict(list)
    for key, node in schema['nodes'].items():
        grouped[(node['namespace'], node['type'].split('.')[0])].append(node)
    for (ns, root), nodes in grouped.items():
        outer = next(v for v in nodes if v['type'] == root)
        folder = REPO / Path(outer['sourceFiles'][0]).parent
        lines = ['// SPDX-License-Identifier: Apache-2.0', '// Copyright 2026 Nils Kopal',
                 '// Generated by scripts/generate-state-code.py; edit the reviewed schema and regenerate.',
                 '#nullable enable',
                 'using DOSEmulator.Core;', *(['using DOSEmulator.Contracts;'] if ns in ['DOSEmulator.Hardware', 'DOSEmulator.Runtime'] else []), 'using System.Text;', '', 'namespace ' + ns + ';', '']
        scheduled = any(v['owner'] == ns + '.' + root for v in events)
        lines.append(('internal' if root == 'AtaPioDrive' else 'public') + ' sealed partial class ' + root + ' : ' + ('IScheduledStateObject' if scheduled else 'IStateObject'))
        lines.extend(['{', accessor(outer, events, callbacks)])
        for node in nodes:
            if node is outer:
                continue
            name = node['type'].split('.')[-1]
            access = 'public' if root == 'PcAudioMixer' else 'private'
            lines.extend(['', '    ' + access + ' sealed partial class ' + name + ' : IStateObject', '    {',
                          '\n'.join('    ' + v for v in accessor(node, events, callbacks).splitlines()), '    }'])
        lines.append('}')
        write(folder / (root + '.State.g.cs'), '\n'.join(lines) + '\n', args.check)
        for node in nodes:
            leaf = node['type'].split('.')[-1]
            for file in node['sourceFiles']:
                path = REPO / file
                text = path.read_bytes().decode('utf-8-sig')
                pattern = r'(?<!partial )\bclass ' + re.escape(leaf) + r'\b'
                updated = re.sub(pattern, 'partial class ' + leaf, text)
                if updated != text:
                    if args.check:
                        raise AssertionError('Component requires partial declaration: ' + file)
                    write(path, updated, False)
    print(json.dumps(dict(passed=True, components=len(schema['nodes']), operations=len(events),
                          reviewedMembers=sum(len(v['fields']) for v in schema['nodes'].values()), check=args.check)))


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--inventory', required=True)
    parser.add_argument('--check', action='store_true')
    main(parser.parse_args())
